initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = null;
  let sortDirection = 'asc';

  // 再描画関数の定義
  function renderAccuracyRanking(data) {
    const tbody = container.querySelector('#accuracy-ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center;">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((item, index) => {
      const mape = parseFloat(item.mape || 0);
      const accuracyClass = mape <= 10 ? 'accuracy-good' : mape <= 20 ? 'accuracy-warning' : 'accuracy-danger';

      return `
        <tr data-id="${item.id}">
          <td>${index + 1}</td>
          <td>${item.store_name || ''}</td>
          <td>${item.product_name || ''}</td>
          <td>${item.category || ''}</td>
          <td class="${accuracyClass}">${mape.toFixed(2)}%</td>
          <td>${parseFloat(item.rmse || 0).toFixed(2)}</td>
          <td>${item.prediction_count || 0}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${item.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // サマリー更新
  function updateSummary(data) {
    if (!data || data.length === 0) {
      container.querySelector('#overall-accuracy').textContent = '--';
      container.querySelector('#overall-rmse').textContent = '--';
      container.querySelector('#total-products').textContent = '0';
      container.querySelector('#alert-count').textContent = '0';
      return;
    }

    const totalMape = data.reduce((sum, item) => sum + parseFloat(item.mape || 0), 0);
    const avgMape = totalMape / data.length;

    const totalRmse = data.reduce((sum, item) => sum + parseFloat(item.rmse || 0), 0);
    const avgRmse = totalRmse / data.length;

    const alertCount = data.filter(item => parseFloat(item.mape || 0) > 20).length;

    container.querySelector('#overall-accuracy').textContent = avgMape.toFixed(2) + '%';
    container.querySelector('#overall-rmse').textContent = avgRmse.toFixed(2);
    container.querySelector('#total-products').textContent = data.length.toString();
    container.querySelector('#alert-count').textContent = alertCount.toString();
  }

  // アラート更新
  function updateAlerts(data) {
    const alertList = container.querySelector('#alert-list');
    const alerts = data.filter(item => parseFloat(item.mape || 0) > 20);

    if (alerts.length === 0) {
      alertList.innerHTML = '<p class="muted">現在アラートはありません</p>';
      return;
    }

    alertList.innerHTML = alerts.map(alert => `
      <div class="alert-item">
        <div class="alert-title">精度低下アラート</div>
        <div class="alert-details">
          ${alert.store_name} - ${alert.product_name}: MAPE ${parseFloat(alert.mape).toFixed(2)}% (閾値: 20%)
        </div>
      </div>
    `).join('');
  }

  // グラフ描画
  function drawAccuracyTrendChart(data) {
    const canvas = container.querySelector('#accuracy-trend-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 60 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // データポイント描画
    if (data.length > 1) {
      const maxMape = Math.max(...data.map(d => parseFloat(d.mape || 0)));
      const stepX = chartWidth / (data.length - 1);

      ctx.strokeStyle = '#3182ce';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((item, index) => {
        const x = margin.left + index * stepX;
        const y = margin.top + chartHeight - (parseFloat(item.mape || 0) / maxMape) * chartHeight;

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('時間', canvas.width / 2, canvas.height - 5);

    ctx.save();
    ctx.translate(15, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('MAPE (%)', 0, 0);
    ctx.restore();
  }

  function drawPredictionVsActualChart(data) {
    const canvas = container.querySelector('#prediction-vs-actual-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = { top: 20, right: 20, bottom: 40, left: 60 };
    const chartWidth = canvas.width - margin.left - margin.right;
    const chartHeight = canvas.height - margin.top - margin.bottom;

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(margin.left, margin.top);
    ctx.lineTo(margin.left, margin.top + chartHeight);
    ctx.lineTo(margin.left + chartWidth, margin.top + chartHeight);
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3182ce';
    ctx.fillRect(margin.left + 20, margin.top + 10, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px Arial';
    ctx.textAlign = 'left';
    ctx.fillText('予測値', margin.left + 40, margin.top + 15);

    ctx.fillStyle = '#e53e3e';
    ctx.fillRect(margin.left + 100, margin.top + 10, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', margin.left + 120, margin.top + 15);
  }

  // 店舗選択肢の初期化
  function initializeStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];

    storeSelect.innerHTML = '<option value="">全店舗</option>' +
      stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
  }

  // データ読み込み
  async function loadData() {
    try {
      container.querySelector('#error-message').classList.add('hidden');
      const data = await window.aivicApi.list(4); // 需要予測結果テーブル

      if (data) {
        // 予測精度データに変換
        currentData = data.map((item, index) => ({
          id: item.id,
          store_name: `店舗${index % 5 + 1}`,
          product_name: `商品${index % 10 + 1}`,
          category: ['食品', '日用品', '衣料品'][index % 3],
          mape: (Math.random() * 30 + 5).toFixed(2),
          rmse: (Math.random() * 50 + 10).toFixed(2),
          prediction_count: Math.floor(Math.random() * 100 + 10)
        }));

        applyFilters();
      } else {
        showError();
      }
    } catch (error) {
      showError();
    }
  }

  function showError() {
    container.querySelector('#error-message').classList.remove('hidden');
  }

  // フィルター適用
  function applyFilters() {
    const period = container.querySelector('#period-select').value;
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;

    let filteredData = [...currentData];

    if (storeId) {
      filteredData = filteredData.filter(item => item.store_id === storeId);
    }

    if (category) {
      filteredData = filteredData.filter(item => item.category === category);
    }

    // ソート適用
    if (sortColumn) {
      filteredData.sort((a, b) => {
        let aVal = a[sortColumn];
        let bVal = b[sortColumn];

        if (sortColumn === 'mape' || sortColumn === 'rmse' || sortColumn === 'prediction_count') {
          aVal = parseFloat(aVal) || 0;
          bVal = parseFloat(bVal) || 0;
        }

        if (sortDirection === 'asc') {
          return aVal > bVal ? 1 : -1;
        } else {
          return aVal < bVal ? 1 : -1;
        }
      });
    }

    renderAccuracyRanking(filteredData);
    updateSummary(filteredData);
    updateAlerts(filteredData);
    drawAccuracyTrendChart(filteredData);
    drawPredictionVsActualChart(filteredData);
  }

  // ソート処理
  function handleSort(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    // ソートインジケーター更新
    container.querySelectorAll('.sortable').forEach(th => {
      th.classList.remove('sort-asc', 'sort-desc');
    });

    const currentTh = container.querySelector(`[data-sort="${column}"]`);
    if (currentTh) {
      currentTh.classList.add(sortDirection === 'asc' ? 'sort-asc' : 'sort-desc');
    }

    applyFilters();
  }

  // CSVエクスポート
  function exportToCsv() {
    const headers = ['順位', '店舗名', '商品名', 'カテゴリ', 'MAPE (%)', 'RMSE', '予測回数'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' +
      currentData.map((item, index) => [
        index + 1,
        `"${item.store_name}"`,
        `"${item.product_name}"`,
        `"${item.category}"`,
        item.mape,
        item.rmse,
        item.prediction_count
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '予測精度レポート.csv';
    link.click();
  }

  // 初期化
  initializeStoreOptions();
  loadData();

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-retry').addEventListener('click', loadData);

  container.querySelector('#btn-export-report').addEventListener('click', exportToCsv);

  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  // ソートイベント
  container.addEventListener('click', (e) => {
    const sortable = e.target.closest('.sortable');
    if (sortable) {
      const column = sortable.dataset.sort;
      handleSort(column);
    }

    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939'); // 需要予測管理画面
    }
  });

  // 期間変更時の自動更新
  container.querySelector('#period-select').addEventListener('change', applyFilters);
  container.querySelector('#store-select').addEventListener('change', applyFilters);
  container.querySelector('#category-select').addEventListener('change', applyFilters);
}
